-- Generated by model/lib/sql/generate.mjs. Loads OPEX IN from cells/OPEX IN.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/OPEX IN.csv
INSERT INTO "OPEX IN" SELECT coalesce(k0."Cost Center", fpabench_error('cells name a member Cost Center does not have: ' || c."Cost Center")), coalesce(k1."Account", fpabench_error('cells name a member Account does not have: ' || c."Account")), coalesce(k2."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k3."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k4."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Cost Center" k0 ON k0.name = c."Cost Center" LEFT JOIN "dim Account" k1 ON k1.name = c."Account" LEFT JOIN "dim Versions" k2 ON k2.name = c."Versions" LEFT JOIN "dim Years" k3 ON k3.name = c."Years" LEFT JOIN "dim Months" k4 ON k4.name = c."Months"
GROUP BY 1, 2, 3, 4, 5
ON CONFLICT ("Cost Center", "Account", "Versions", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "OPEX IN";
